import { isArraysEqualDeeply } from "../../utils/compareElementsUtils/isArraysEqualDeeply";
export const removeTrendDataFromDatasets = (datasets) => datasets.filter((dataset) => {
    if (!("trendData" in dataset)) {
        return true;
    }
    return !isArraysEqualDeeply(dataset.data, dataset.trendData);
});
